<template><main class="assistant-page" aria-label="AI 助手管理"><div class="assistant-title"><div><h1>{{zh?'AI 助手':localize('AI assistant')}}</h1><p>{{zh?'管理模型连接、技能与 MCP 服务。配置保存在本机，API 密钥加密保存。':localize('Manage model connections, skills and MCP services. Settings stay local; API keys are encrypted.')}}</p></div><div class="settings-history"><button :disabled="busy||!canUndoSettings" @click="moveSettings()">{{zh?'撤销设置':localize('Undo settings')}}</button><button :disabled="busy||!canRedoSettings" @click="moveSettings(true)">{{zh?'重做设置':localize('Redo settings')}}</button><button class="primary" :disabled="busy" @click="save">{{zh?'保存设置':localize('Save settings')}}</button></div></div><nav role="tablist"><button v-for="item in [['models','模型管理','Models'],['skills','技能','Skills'],['mcp','MCP','MCP'],['connection','软件连接','CAD connection']]" :key="item[0]" role="tab" :aria-selected="tab===item[0]" :class="{active:tab===item[0]}" @click="tab=item[0]">{{zh?item[1]:localize(item[2])}}</button></nav><p v-if="message" :role="failed?'alert':'status'" :class="{error:failed}">{{message}}</p><section role="tabpanel"><InlineActivity v-if="working" :label="zh?'正在处理助手设置…':localize('Processing assistant settings…')"/><fieldset :disabled="busy">
<AssistantModels v-if="tab==='models'" :config="config" :language="language" @models="models"/>
<template v-else-if="tab==='skills'"><p>{{zh?'导入或编写技能说明，按需启用。保存配置不会执行技能中的命令。':localize('Import or write skill instructions and enable them as needed. Saving a skill does not execute its commands.')}}</p><label>{{zh?'导入 SKILL.md':localize('Import SKILL.md')}}<input type="file" accept=".md,.txt" @change="importSkill"></label><article v-for="s in config.skills" :key="s.id"><div class="row"><input v-model="s.enabled" type="checkbox" :aria-label="zh?'启用技能':localize('Enable skill')"><input v-model="s.name" :aria-label="zh?'技能名称':localize('Skill name')"><button @click="config.skills=config.skills.filter(v=>v.id!==s.id)">{{zh?'删除':localize('Delete')}}</button></div><textarea v-model="s.content" rows="10" :aria-label="zh?'技能内容':localize('Skill instructions')"/></article><button @click="config.skills.push({id:newId(),name:zh?'新技能':localize('New skill'),content:'',enabled:true})">＋ {{zh?'新建技能':localize('New skill')}}</button></template>
<template v-else-if="tab==='mcp'"><p>{{zh?'支持 Streamable HTTP MCP 服务。连接测试读取工具清单，不会执行工具。':localize('Streamable HTTP MCP servers. Connection tests list tools without executing them.')}}</p><article v-for="s in config.mcp" :key="s.id"><div class="row"><input v-model="s.enabled" type="checkbox" :aria-label="zh?'启用 MCP':localize('Enable MCP')"><input v-model="s.name" :aria-label="zh?'MCP 名称':localize('MCP name')"><button @click="config.mcp=config.mcp.filter(v=>v.id!==s.id)">{{zh?'删除':localize('Delete')}}</button></div><label>URL<input v-model="s.url" type="url"></label><button @click="testMcp(s.id)">{{zh?'测试连接并查看工具':localize('Test connection and list tools')}}</button></article><button @click="config.mcp.push({id:newId(),name:zh?'本地 MCP':localize('Local MCP'),url:'http://127.0.0.1:8000/mcp',enabled:true})">＋ {{zh?'添加 MCP':localize('Add MCP')}}</button></template>
<AssistantConnection v-else :language="language"/>
</fieldset></section></main></template>

<script setup lang="ts">
import {localize} from './localization';
import InlineActivity from './InlineActivity.vue';
import {useDelayedActivity} from './modules/useDelayedActivity';

import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {DraftHistory} from '../../../packages/ui/draft-history';
import AssistantConnection from './AssistantConnection.vue';
import AssistantModels from './AssistantModels.vue';
import {defaultAssistantConfig,type AssistantConfig,type AssistantSettingsRequest} from '../../../packages/schema/assistant-config';
const newId=()=>crypto.randomUUID();
const props=defineProps<{language:'zh'|'en'}>(),zh=computed(()=>props.language==='zh'),config=ref<AssistantConfig>(defaultAssistantConfig()),tab=ref('models'),busy=ref(false),message=ref(''),failed=ref(false);
const working=useDelayedActivity(()=>busy.value);
// Settings drafts have their own in-memory history. Credentials never enter
// the CAD repository, and a successful settings response starts a new boundary.
const settingsHistory=new DraftHistory<AssistantConfig>(),historyVersion=ref(0);
let previousConfig=JSON.stringify(config.value),disposed=false;
const canUndoSettings=computed(()=>{historyVersion.value;return settingsHistory.canUndo;}),canRedoSettings=computed(()=>{historyVersion.value;return settingsHistory.canRedo;});
watch(()=>JSON.stringify(config.value),value=>{if(value!==previousConfig){settingsHistory.record(JSON.parse(previousConfig),JSON.parse(value));previousConfig=value;historyVersion.value++;}},{flush:'post'});
function replaceConfig(value:AssistantConfig){config.value=value;previousConfig=JSON.stringify(value);settingsHistory.clear();historyVersion.value++;}
function moveSettings(redo=false){if(busy.value)return;const value=settingsHistory.move(JSON.parse(JSON.stringify(config.value)),redo);if(value){config.value=value;previousConfig=JSON.stringify(value);historyVersion.value++;}}
function settingsKey(event:KeyboardEvent){if(event.target instanceof Element&&event.target.closest('.modal-backdrop'))return;if(!(event.ctrlKey||event.metaKey))return;const key=event.key.toLowerCase();if(key!=='z'&&key!=='y')return;if(event.target instanceof Element&&event.target.closest('textarea,[contenteditable=true],input:not([type=number]):not([type=range]):not([type=checkbox]):not([type=radio]):not([type=color])'))return;event.preventDefault();event.stopPropagation();moveSettings(key==='y'||event.shiftKey);}
async function run(request:AssistantSettingsRequest){if(disposed||busy.value)return false;busy.value=true;message.value='';failed.value=false;try{const r=await window.fpcad.assistantSettings(request);if(disposed)return false;if(!r.ok)throw Error(r.error);replaceConfig(r.config);message.value=request.action==='read'?'':r.tools?(zh.value?'已连接，工具：':localize('Connected, tools: '))+r.tools.join(', '):r.models?(zh.value?'已获取模型：':localize('Models loaded: '))+r.models.length:(zh.value?'设置已保存':localize('Settings saved'));return true;}catch(e){if(!disposed){failed.value=true;message.value=errorText(String(e instanceof Error?e.message:e));}return false;}finally{if(!disposed)busy.value=false;}}
function errorText(message:string){
 const keys:Record<string,[string,string]>={MCP_RESPONSE_INVALID:['MCP 服务响应格式无效，请核对服务地址。','Invalid MCP response. Check the server address.'],MCP_PAGINATION_INVALID:['MCP 工具清单分页无效，请检查服务响应。','Invalid MCP tool list pagination.'],MCP_TOOLS_INVALID:['MCP 服务返回的工具清单格式无效。','Invalid MCP tool list.'],PROVIDER_MANUAL_MODELS:['请在模型管理中填写控制台提供的模型或推理接入点标识。','Enter the model or endpoint ID from the provider console in Models.'],HTTP_REQUIRES_OPT_IN:['此服务使用 HTTP，请勾选该卡片的“允许 HTTP 连接”，或改用 HTTPS 地址。','Enable HTTP for this provider or use an HTTPS address.'],INVALID_ENDPOINT:['请输入完整的 HTTP 或 HTTPS 服务地址，不含账号、密码或查询参数。','Enter an HTTP or HTTPS base URL without credentials or query parameters.'],MODEL_LIST_INVALID:['服务返回的模型清单格式不匹配，请核对提供商类型和接口地址。','Model list does not match this provider protocol. Check provider type and base URL.'],PROVIDER_CHANGED:['提供商配置已改变，请重新获取模型。','Provider changed. Fetch models again.'],PROVIDER_UNAVAILABLE:['提供商不存在或未启用。','Provider is missing or disabled.'],MODEL_PAGINATION_INVALID:['模型列表分页无效，请检查服务响应。','Invalid model list pagination.']};
 for(const [key,text] of Object.entries(keys))if(message.includes(key))return localize(text[zh.value?0:1]);
 if(message.startsWith('PROVIDER_HTTP_'))return (zh.value?'连接失败，服务状态码：':localize('Connection failed, HTTP status: '))+message.slice(14);
 if(message.includes('fetch failed'))return zh.value?'无法连接服务，请检查地址、端口与服务是否启动。':localize('Cannot connect. Check address, port and server availability.');
 if(message.startsWith('['))return zh.value?'设置不完整，请检查提供商名称、地址和所选模型。':localize('Check provider name, address and model selection.');
 return message;
}
const save=()=>run({action:'save',config:JSON.parse(JSON.stringify(config.value))});
async function models(id:string){if(await save())await run({action:'models',providerId:id});}
async function testMcp(id:string){if(await save())await run({action:'mcp-test',serverId:id});}
async function importSkill(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(disposed||busy.value||!file)return;if(file.size>100000){failed.value=true;message.value=zh.value?'技能文件过大':localize('Skill file too large');input.value='';return;}busy.value=true;failed.value=false;message.value='';try{const content=await file.text();if(!disposed)config.value.skills.push({id:newId(),name:file.name,content,enabled:true});}catch{if(!disposed){failed.value=true;message.value=zh.value?'无法读取技能文件，请重新选择。':localize('Could not read the skill file. Select it again.');}}finally{input.value='';if(!disposed)busy.value=false;}}
onMounted(()=>{window.addEventListener('keydown',settingsKey);void run({action:'read'});});onUnmounted(()=>{disposed=true;window.removeEventListener('keydown',settingsKey);});
</script>

<style scoped>
.assistant-page{flex:1;min-width:0;min-height:0;overflow:auto;padding:32px clamp(20px,4vw,56px) 48px;background:var(--bg)}.assistant-title{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;max-width:1120px}.assistant-title h1{margin:0;color:var(--text);font-size:26px;font-weight:650;line-height:1.3;letter-spacing:-.5px}.assistant-title p{max-width:70ch;margin:10px 0 0;font-size:12px}.settings-history{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;flex:none;padding-top:2px}.settings-history button{min-height:32px;padding:6px 12px;font-size:12px}
.assistant-page nav{display:flex;gap:3px;width:fit-content;max-width:100%;height:auto;overflow-x:auto;margin:24px 0;padding:4px;border:1px solid var(--border);border-radius:10px;background:var(--panel-soft)}.assistant-page nav button{min-height:31px;padding:6px 16px;border:1px solid transparent;border-radius:var(--radius-control);color:var(--text-muted);font-size:12px;box-shadow:none}.assistant-page nav button.active{border-color:color-mix(in srgb,var(--accent) 16%,var(--border));background:var(--panel);color:var(--accent);font-weight:600;box-shadow:0 1px 3px color-mix(in srgb,var(--shadow-color) 8%,transparent)}
.assistant-page>p{max-width:1120px;margin:0 0 20px;padding:12px 14px;border:1px solid var(--border);border-radius:var(--radius-control);background:var(--panel);color:var(--text)}.assistant-page>p.error{color:var(--danger);background:var(--danger-soft);border-color:color-mix(in srgb,var(--danger) 25%,var(--border))}section{max-width:1120px}fieldset{min-width:0;margin:0;padding:0;border:0}fieldset>p:first-child{margin-top:0}article{min-width:0;margin:16px 0;padding:20px;border:1px solid var(--border);border-radius:var(--radius-panel);background:var(--panel)}.row{display:flex;align-items:center;gap:12px;margin-bottom:12px}.row input:not([type=checkbox]){flex:1;min-width:0}.row input[type=checkbox]{flex:none;width:16px;height:16px;margin:0}.row button{flex:none}.assistant-page fieldset>label{display:grid;gap:8px;max-width:440px;margin:16px 0}.assistant-page article>label{display:grid;gap:8px;margin:14px 0}.assistant-page article>label input{margin:0}textarea{display:block;width:100%;min-height:160px;margin-top:16px;padding:12px;resize:vertical;font:12px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace}p,small{color:var(--text-muted);font-size:12px;line-height:1.7}small{display:block;margin-top:8px}.error{color:var(--danger)}
@media(max-width:1100px){.assistant-title{flex-direction:column;gap:16px}.settings-history{justify-content:flex-start;flex:initial}.assistant-page{padding:24px}.assistant-page nav{margin-block:20px}.assistant-page nav button{padding-inline:12px}}
@media(max-width:700px){.assistant-page{padding:20px 16px}.assistant-title h1{font-size:23px}.assistant-page nav{width:100%}.assistant-page nav button{flex:1;padding-inline:10px}article{padding:16px}.row{gap:8px}}
</style>
